"use client";

import { forwardRef, type ComponentProps } from "react";
import LegacySearchList from "../beautiful-ui/primitives/SearchList";
import { BeautifulUIRoot } from "../beautiful-ui/BeautifulUIRoot";

export type SearchListProps = NonNullable<ComponentProps<typeof LegacySearchList>>;

export const SearchList = forwardRef<HTMLDivElement, SearchListProps>((props, ref) => (
  <BeautifulUIRoot ref={ref}>
    <LegacySearchList {...props} />
  </BeautifulUIRoot>
));

SearchList.displayName = "SearchList";

export default SearchList;

"use client";

import { useId, useMemo, useRef, useState } from "react";
import { useIcon } from "@/lib/icon-context";
import { useShape } from "@/lib/shape-context";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "../hooks/useReducedMotion";
import GlideMenu from "./GlideMenu";
import "../beautiful-ui.css";

const DEFAULT_ITEMS = [
  "Forecast summer demand",
  "Find waffle cone suppliers",
  "Compare seasonal flavors",
  "Draft flavor launch plan",
  "Check cold-chain status",
  "Audit sugar costs",
  "Retire low sellers",
];

export interface SearchListProps {
  items?: readonly string[];
  query?: string;
  defaultQuery?: string;
  placeholder?: string;
  onQueryChange?: (query: string) => void;
  onSelect?: (item: string) => void;
}

export default function SearchList({
  items = DEFAULT_ITEMS,
  query: controlledQuery,
  defaultQuery = "",
  placeholder = "Search flavors…",
  onQueryChange,
  onSelect,
}: SearchListProps = {}) {
  const shape = useShape();
  const SearchIcon = useIcon("search");
  const CloseIcon = useIcon("x");
  const reducedMotion = useReducedMotion();
  const listboxId = useId();
  const inputRef = useRef<HTMLInputElement>(null);
  const [internalQuery, setInternalQuery] = useState(defaultQuery);
  const [open, setOpen] = useState(true);
  const [activeIndex, setActiveIndex] = useState(0);
  const query = controlledQuery ?? internalQuery;

  const results = useMemo(
    () =>
      query
        ? items.filter((item) => item.toLowerCase().includes(query.toLowerCase()))
        : items.slice(0, 5),
    [items, query],
  );
  const empty = query.length > 2 && results.length === 0;
  const currentIndex = results.length === 0 ? -1 : Math.min(activeIndex, results.length - 1);

  const updateQuery = (next: string) => {
    if (controlledQuery === undefined) setInternalQuery(next);
    onQueryChange?.(next);
    setActiveIndex(0);
    setOpen(true);
  };

  const selectItem = (item: string) => {
    if (controlledQuery === undefined) setInternalQuery(item);
    onQueryChange?.(item);
    onSelect?.(item);
    setOpen(false);
    setActiveIndex(0);
    inputRef.current?.focus({ preventScroll: true });
  };

  return (
    <div className="flex min-h-[248px] w-full max-w-72 flex-col items-stretch">
      <div
        data-bui-input-group=""
        className={cn(
          "w-full self-start overflow-hidden bg-[var(--surface)] shadow-surface-2",
          shape.container,
        )}
        style={{ outlineColor: "var(--border)" }}
      >
        <div className="flex h-10 items-center gap-2 border-b border-border/40 px-3 transition-colors duration-80 hover:bg-hover">
          <SearchIcon size={14} strokeWidth={1.5} className="shrink-0 text-[var(--ink-3)]" />
          <input
            ref={inputRef}
            type="search"
            role="combobox"
            aria-autocomplete="list"
            aria-expanded={open}
            aria-controls={listboxId}
            aria-activedescendant={
              open && currentIndex >= 0 ? `${listboxId}-option-${currentIndex}` : undefined
            }
            value={query}
            onFocus={() => setOpen(true)}
            onChange={(event) => updateQuery(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === "Escape") {
                event.preventDefault();
                setOpen(false);
                setActiveIndex(0);
                return;
              }
              if (results.length === 0) return;
              if (event.key === "ArrowDown" || event.key === "ArrowUp") {
                event.preventDefault();
                setOpen(true);
                setActiveIndex((current) => {
                  const bounded = Math.min(current, results.length - 1);
                  const direction = event.key === "ArrowDown" ? 1 : results.length - 1;
                  return (bounded + direction) % results.length;
                });
                return;
              }
              if (event.key === "Home" || event.key === "End") {
                event.preventDefault();
                setOpen(true);
                setActiveIndex(event.key === "Home" ? 0 : results.length - 1);
                return;
              }
              if (event.key === "Enter" && open && currentIndex >= 0) {
                event.preventDefault();
                selectItem(results[currentIndex]);
              }
            }}
            placeholder={placeholder}
            aria-label="Search flavors"
            className="min-w-0 flex-1 appearance-none rounded-none border-0 bg-transparent p-0 text-[13px] text-foreground shadow-none outline-none focus:outline-none focus-visible:outline-none placeholder:text-muted-foreground [&::-webkit-search-cancel-button]:hidden [&::-webkit-search-decoration]:hidden"
          />
          {query ? (
            <button
              aria-label="Clear search"
              type="button"
              onClick={() => {
                updateQuery("");
                inputRef.current?.focus({ preventScroll: true });
              }}
              className={cn(
                "flex size-8 shrink-0 appearance-none items-center justify-center border-0 bg-transparent p-0 text-muted-foreground transition-[background-color,color,transform] duration-80 hover:bg-hover hover:text-foreground active:scale-[0.98]",
                shape.button,
              )}
              style={{ animation: reducedMotion ? undefined : "fade-in 160ms ease-out both" }}
            >
              <CloseIcon size={14} strokeWidth={1.5} />
            </button>
          ) : null}
        </div>

        {open ? (
          empty ? (
            <div
              id={listboxId}
              role="listbox"
              aria-label="Search results"
              className="flex flex-col items-center justify-center gap-1 px-4 py-8"
              style={{ animation: reducedMotion ? undefined : "fade-in 240ms ease-out both" }}
            >
              <span
                className={cn(
                  "mb-1.5 flex size-8 items-center justify-center bg-hover text-muted-foreground",
                  shape.item,
                )}
              >
                <SearchIcon size={15} strokeWidth={1.5} />
              </span>
              <span className="text-[13px] font-medium text-[var(--ink)]">No results found</span>
              <span className="text-[12px] text-[var(--ink-3)]">
                Adjust your search to try again
              </span>
            </div>
          ) : (
            <div id={listboxId} role="listbox" aria-label="Search results" className="p-1">
              <GlideMenu
                className="flex flex-col gap-px"
                highlightClassName={`inset-x-0 ${shape.item} bg-hover`}
              >
                {results.map((item, index) => (
                  <button
                    key={item}
                    id={`${listboxId}-option-${index}`}
                    data-menu-row
                    type="button"
                    role="option"
                    aria-selected={index === currentIndex}
                    tabIndex={-1}
                    onMouseEnter={() => setActiveIndex(index)}
                    onClick={() => selectItem(item)}
                    className={`relative z-10 flex h-8 w-full appearance-none items-center ${shape.item} border-0 px-2 text-left text-[13px] text-foreground ${
                      index === currentIndex ? "bg-hover" : "bg-transparent"
                    }`}
                    style={{ animation: reducedMotion ? undefined : "fade-in 160ms ease-out both" }}
                  >
                    {item}
                  </button>
                ))}
              </GlideMenu>
            </div>
          )
        ) : null}
      </div>

      <span role="status" aria-live="polite" className="sr-only">
        {open ? `${results.length} ${results.length === 1 ? "result" : "results"} available` : ""}
      </span>
    </div>
  );
}

"use client";

import "./beautiful-ui.css";
import { forwardRef, type CSSProperties, type HTMLAttributes } from "react";
import { SurfaceProvider, useSurface } from "@/lib/surface-context";
import { useShapeVariant } from "@/lib/shape-context";

export type BeautifulUIRootProps = HTMLAttributes<HTMLDivElement>;

type AdapterStyle = CSSProperties & Record<`--${string}`, string | number>;

function clampSurface(level: number) {
  return Math.max(1, Math.min(8, level));
}

function createAdapterStyle(
  substrate: number,
  surface: number,
  style?: CSSProperties,
): AdapterStyle {
  const inset = clampSurface(substrate + 1);
  const overlay = clampSurface(surface + 2);
  const raisedOverlay = clampSurface(surface + 4);

  return {
    "--page": `var(--surface-${substrate})`,
    "--canvas": `var(--surface-${substrate})`,
    "--surface": `var(--surface-${surface})`,
    "--inset": `var(--surface-${inset})`,
    "--tooltip-bg": `var(--surface-${overlay})`,
    "--overlay-surface": `var(--surface-${overlay})`,
    "--overlay-raised": `var(--surface-${raisedOverlay})`,
    ...style,
  };
}

function useBeautifulUIScope(offset = 2) {
  const substrate = useSurface();
  const surface = clampSurface(substrate + offset);
  const shape = useShapeVariant();

  return {
    shape,
    substrate,
    surface,
    style: createAdapterStyle(substrate, surface),
  };
}

/**
 * Internal compatibility boundary for the adapted primitives. It has no layout
 * box of its own: public components use it internally so consumers inherit the
 * active BoringUI theme, surface level, and radius mode without a wrapper.
 */
export const BeautifulUIRoot = forwardRef<HTMLDivElement, BeautifulUIRootProps>(
  ({ className, style, ...props }, ref) => {
    const scope = useBeautifulUIScope();

    return (
      <SurfaceProvider value={scope.surface}>
        <div
          ref={ref}
          data-bui-component=""
          data-shape={scope.shape}
          data-surface={scope.surface}
          className={["beautiful-ui", "contents", className].filter(Boolean).join(" ")}
          style={{ ...scope.style, ...style }}
          {...props}
        />
      </SurfaceProvider>
    );
  },
);

BeautifulUIRoot.displayName = "BeautifulUIRoot";

/** Applies the same BoringUI scope to content rendered in a body portal. */
export const BeautifulUIPortalRoot = forwardRef<HTMLDivElement, BeautifulUIRootProps>(
  ({ className, style, ...props }, ref) => {
    const scope = useBeautifulUIScope();

    return (
      <SurfaceProvider value={scope.surface}>
        <div
          ref={ref}
          data-bui-component=""
          data-shape={scope.shape}
          data-surface={scope.surface}
          className={["beautiful-ui", className].filter(Boolean).join(" ")}
          style={{ ...scope.style, ...style }}
          {...props}
        />
      </SurfaceProvider>
    );
  },
);

BeautifulUIPortalRoot.displayName = "BeautifulUIPortalRoot";

export default BeautifulUIRoot;

