.beautiful-ui {
  /* Compatibility aliases only. The source of truth is BoringUI's global
     theme, surface, interaction, and status palette. */
  --ink: var(--foreground);
  --ink-2: var(--muted-foreground);
  --ink-3: var(--muted-foreground);
  --line: var(--border);
  --line-strong: color-mix(in oklab, var(--foreground) 20%, transparent);
  --field: var(--accent);
  --stripe: color-mix(in oklab, var(--foreground) 8%, transparent);
  --stripe-bg: var(--muted);
  --hover-2: var(--active);

  --bui-focus: #6b97ff;
  --bui-focus-ink: color-mix(in srgb, var(--bui-focus) 62%, var(--foreground));
  --bui-focus-tint: color-mix(in srgb, var(--bui-focus) 15%, var(--background));
  --green-base: #22c55e;
  --green: color-mix(in srgb, var(--green-base) 62%, var(--foreground));
  --green-tint: color-mix(in srgb, var(--green-base) 15%, var(--background));
  --orange-base: #f97316;
  --orange: color-mix(in srgb, var(--orange-base) 62%, var(--foreground));
  --orange-tint: color-mix(in srgb, var(--orange-base) 15%, var(--background));
  --amber: #f59e0b;
  --cyan: #06b6d4;
  --purple: #a855f7;
  --red: color-mix(in srgb, var(--destructive) 68%, var(--foreground));
  --red-tint: var(--destructive-light);

  --tooltip-fg: var(--foreground);
  --tooltip-muted: var(--muted-foreground);
  --tooltip-border: var(--border);

  --shadow-hairline: var(--shadow-1);
  --shadow-btn: var(--shadow-2);
  --shadow-card: var(--shadow-3);
  --shadow-raised: var(--shadow-4);
  --shadow-overlay: var(--shadow-5);
  --shadow-inset-field: inset 0 0 0 1px var(--border);

  /* Size-aware radii. True pills opt into rounded-full explicitly; compact
     menus and cards must not inherit the app shell's 24px container radius. */
  --radius-chip: 6px;
  --radius-control: 8px;
  --radius-menu: 10px;
  --radius-card: 12px;
  --radius-window: 14px;

  --font-sans: "Inter", system-ui, sans-serif;
  --font-mono: ui-monospace, "SFMono-Regular", Consolas, "Liberation Mono", monospace;

  --ease-out-strong: cubic-bezier(0.23, 1, 0.32, 1);
  --ease-in-out-strong: cubic-bezier(0.77, 0, 0.175, 1);
  --ease-link: cubic-bezier(0.16, 1, 0.3, 1);

  color: var(--ink);
  font-family: var(--font-sans);
}

.beautiful-ui[data-shape="rounded"] {
  --radius-chip: 4px;
  --radius-control: 6px;
  --radius-menu: 8px;
  --radius-card: 10px;
  --radius-window: 12px;
}

.beautiful-ui :is(h1, h2, h3, h4) {
  text-wrap: balance;
}

.beautiful-ui p {
  text-wrap: pretty;
}

.beautiful-ui .font-mono {
  font-family: var(--font-mono);
}

.beautiful-ui .font-medium {
  font-weight: 450;
  font-variation-settings: "wght" 450;
}

.beautiful-ui .font-semibold {
  font-weight: 550;
  font-variation-settings: "wght" 550;
}

.beautiful-ui .font-bold {
  font-weight: 700;
  font-variation-settings: "wght" 700;
}

.beautiful-ui ::selection {
  background: var(--bui-focus-tint);
  color: var(--ink);
}

.beautiful-ui button:not(:disabled),
.beautiful-ui [role="button"]:not([aria-disabled="true"]),
.beautiful-ui label:has(input),
.beautiful-ui a {
  cursor: pointer;
}

/* Keep text-entry resets below utilities so field surfaces, borders,
   typography, and deliberate shadows remain owned by each primitive.
   Native range and discrete controls retain their affordances. */
@layer base {
  .beautiful-ui
    :where(
      textarea,
      [contenteditable=""],
      [contenteditable="true" i],
      [contenteditable="plaintext-only" i],
      input:not([type]),
      input[type="text" i],
      input[type="search" i],
      input[type="email" i],
      input[type="url" i],
      input[type="tel" i],
      input[type="password" i],
      input[type="number" i]
    ) {
    -webkit-appearance: none;
    appearance: none;
    border: 0;
    background-color: transparent;
    box-shadow: none;
    font: inherit;
    color: inherit;
  }

  .beautiful-ui input[type="number" i] {
    -moz-appearance: textfield;
    appearance: textfield;
  }

  .beautiful-ui input[type="number" i]::-webkit-inner-spin-button,
  .beautiful-ui input[type="number" i]::-webkit-outer-spin-button {
    -webkit-appearance: none;
    appearance: none;
    margin: 0;
  }

  .beautiful-ui input[type="search" i]::-webkit-search-decoration,
  .beautiful-ui input[type="search" i]::-webkit-search-cancel-button,
  .beautiful-ui input[type="search" i]::-webkit-search-results-button,
  .beautiful-ui input[type="search" i]::-webkit-search-results-decoration {
    -webkit-appearance: none;
    appearance: none;
    display: none;
  }
}

.beautiful-ui :focus-visible {
  outline: 1px solid var(--bui-focus);
  outline-offset: 2px;
}

/* Standalone text fields retain a neutral focus boundary. Grouped fields
   delegate it to their surface, without changing fill or corner geometry. */
.beautiful-ui
  :is(
    textarea,
    [contenteditable=""],
    [contenteditable="true" i],
    [contenteditable="plaintext-only" i],
    input:not([type]),
    input[type="text" i],
    input[type="search" i],
    input[type="email" i],
    input[type="url" i],
    input[type="tel" i],
    input[type="password" i],
    input[type="number" i]
  ):focus {
  outline: 1px solid var(--line-strong);
  outline-offset: 2px;
}

/* Preserve the existing native-select exclusion; no primitive uses one. */
.beautiful-ui select:focus-visible {
  outline: none;
  outline-offset: 0;
}

.beautiful-ui :is([data-bui-input-group], [data-slot="input-group"]):focus-within {
  outline: 1px solid var(--line-strong);
  outline-offset: -1px;
}

.beautiful-ui [data-bui-input-group] [role="slider"]:focus {
  outline: none;
  outline-offset: 0;
}

.beautiful-ui
  :is([data-bui-input-group], [data-slot="input-group"])
  :is(
    textarea,
    [contenteditable=""],
    [contenteditable="true" i],
    [contenteditable="plaintext-only" i],
    input:not([type]),
    input[type="text" i],
    input[type="search" i],
    input[type="email" i],
    input[type="url" i],
    input[type="tel" i],
    input[type="password" i],
    input[type="number" i]
  ) {
  border: 0;
  background-color: transparent;
  box-shadow: none;
  outline: none;
  outline-offset: 0;
}

.beautiful-ui .animated-underline {
  position: relative;
  display: inline-block;
}

.beautiful-ui .animated-underline::after {
  position: absolute;
  right: 0;
  bottom: -1px;
  left: 0;
  height: 1px;
  content: "";
  background: currentColor;
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 240ms var(--ease-link);
}

.beautiful-ui a:hover .animated-underline::after,
.beautiful-ui a:focus-visible .animated-underline::after {
  transform: scaleX(1);
}

.beautiful-ui .primitive-showcase {
  -webkit-user-select: none;
  user-select: none;
  -webkit-touch-callout: none;
}

@media (hover: none) and (pointer: coarse) {
  .beautiful-ui .primitive-showcase {
    -webkit-user-select: none;
    user-select: none;
    -webkit-touch-callout: none;
  }

  .beautiful-ui .primitive-showcase :is(input, textarea, [contenteditable="true"], pre, code) {
    -webkit-user-select: text;
    user-select: text;
    -webkit-touch-callout: default;
  }

  .beautiful-ui .primitive-showcase :is(a, button, [role="button"]) {
    -webkit-tap-highlight-color: transparent;
  }

  .beautiful-ui .primitive-showcase :is(img, svg, canvas) {
    -webkit-user-drag: none;
  }

  .beautiful-ui .insight-chart-stage {
    touch-action: pan-y;
  }
}

.beautiful-ui .source-avatar {
  box-shadow: var(--shadow-1);
}

.beautiful-ui .primitive-card-pad {
  padding: 16px;
}

.beautiful-ui .primitive-card-bar {
  padding: 12px 16px;
}

.beautiful-ui .primitive-card-footer {
  padding: 12px 16px;
}

.beautiful-ui .primitive-table-cell {
  padding: 10px 12px;
}

.beautiful-ui .primitive-icon-button {
  display: inline-flex;
  width: 28px;
  height: 28px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-control);
}

@keyframes shimmer-text {
  from {
    background-position: 150% center;
  }
  to {
    background-position: -50% center;
  }
}

@keyframes fade-up {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.beautiful-ui .home-reveal {
  will-change: opacity, transform, filter;
}

.beautiful-ui .sidebar-row {
  width: 208px;
  transition-duration: var(--sidebar-copy-duration);
  transition-timing-function: var(--sidebar-easing);
}

.beautiful-ui .sidebar-copy {
  opacity: 1;
  transform: translateX(0);
  transition:
    opacity var(--sidebar-copy-duration) ease-out,
    transform var(--sidebar-copy-duration) var(--sidebar-easing);
}

.beautiful-ui .sidebar-logo,
.beautiful-ui .sidebar-collapse-control,
.beautiful-ui .sidebar-expand-control {
  transition-duration: var(--sidebar-copy-duration);
  transition-timing-function: ease-out;
}

.beautiful-ui .sidebar-expand-control {
  pointer-events: none;
  opacity: 0;
}

.beautiful-ui .sidebar-glide-highlight {
  right: 8px;
  left: 8px;
}

.beautiful-ui [data-sidebar-collapsed="true"] .sidebar-row {
  width: 36px;
}

.beautiful-ui [data-sidebar-collapsed="true"] .sidebar-copy {
  pointer-events: none;
  opacity: 0;
  transform: translateX(calc(var(--sidebar-copy-offset) * -1));
}

.beautiful-ui [data-sidebar-collapsed="true"] .sidebar-workspace-control {
  pointer-events: none;
}

.beautiful-ui [data-sidebar-collapsed="true"] .sidebar-logo,
.beautiful-ui [data-sidebar-collapsed="true"] .sidebar-collapse-control {
  pointer-events: none;
  opacity: 0;
}

.beautiful-ui [data-sidebar-collapsed="true"] .sidebar-expand-control {
  pointer-events: auto;
  opacity: 1;
}

.beautiful-ui [data-sidebar-collapsed="true"] .sidebar-glide-highlight {
  right: auto;
  width: 36px;
}

@media (prefers-reduced-motion: reduce) {
  .beautiful-ui .home-reveal {
    opacity: 1 !important;
    transform: none !important;
    filter: none !important;
  }
}

.beautiful-ui .records-shell {
  width: 100%;
  min-width: 0;
  overflow: hidden;
  border: 0;
  border-radius: var(--records-container-radius, var(--radius-card));
  background: var(--surface);
  box-shadow: var(--shadow-2);
}

.beautiful-ui .records-shell.is-fill {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  height: 100%;
  border: 0;
  border-radius: 0;
  box-shadow: none;
}

.beautiful-ui .records-shell.is-fill .records-scroll {
  max-height: none;
  flex: 1;
}

.beautiful-ui .records-toolbar {
  display: flex;
  min-height: 52px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 10px;
  border-bottom: 1px solid color-mix(in oklab, var(--line) 40%, transparent);
  background: var(--surface);
}

.beautiful-ui .records-toolbar-left,
.beautiful-ui .records-toolbar-right,
.beautiful-ui .records-company-header,
.beautiful-ui .records-quiet-button,
.beautiful-ui .records-secondary-button,
