  -webkit-mask-image: linear-gradient(to right, black 20%, rgb(0 0 0 / 0.2));
  mask-image: linear-gradient(to right, black 20%, rgb(0 0 0 / 0.2));
}

.beautiful-ui .stream-caret {
  display: inline-block;
  width: 2px;
  height: 1.05em;
  margin-left: 1.5px;
  translate: 0 -0.5px;
  border-radius: 1px;
  background: var(--ink);
  vertical-align: text-bottom;
  animation: caret-blink 1s step-end infinite;
}

.beautiful-ui .stream-caret.is-streaming {
  animation: none;
}

@keyframes caret-blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .beautiful-ui .stream-caret {
    animation: none;
  }

  .beautiful-ui .stream-tail {
    filter: none;
    -webkit-mask-image: none;
    mask-image: none;
  }
}

.beautiful-ui .records-filter-menu,
.beautiful-ui .insight-chart-tooltip {
  transform-origin: top left;
}

@keyframes pop-in {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes pixel-on {
  0%,
  100% {
    opacity: 0.15;
  }
  18%,
  42% {
    opacity: 1;
  }
  62% {
    opacity: 0.15;
  }
}

@media (prefers-reduced-motion: reduce) {
  .beautiful-ui *,
  .beautiful-ui *::before,
  .beautiful-ui *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
.beautiful-ui .records-header-group {
  display: flex;
  align-items: center;
  gap: 0;
  padding: 0;
}

"use client";

import {
  useCallback,
  useLayoutEffect,
  useRef,
  useState,
  type AriaRole,
  type KeyboardEvent as ReactKeyboardEvent,
  type ReactNode,
} from "react";
import { useReducedMotion } from "../hooks/useReducedMotion";
import "../beautiful-ui.css";

type GlideMenuProps = {
  children: ReactNode;
  className?: string;
  highlightClassName?: string;
  rowSelector?: string;
  role?: AriaRole;
  ariaLabel?: string;
};

/** A single hover layer that glides between interactive menu rows. */
export default function GlideMenu({
  children,
  className = "",
  highlightClassName = "inset-x-0 rounded-[var(--radius-control)] bg-[var(--hover)]",
  rowSelector = "[data-menu-row]",
  role,
  ariaLabel,
}: GlideMenuProps) {
  const reducedMotion = useReducedMotion();
  const ref = useRef<HTMLDivElement>(null);
  const activeRowRef = useRef<HTMLElement | null>(null);
  const [box, setBox] = useState<{ top: number; height: number } | null>(null);
  const [visible, setVisible] = useState(false);

  const measure = useCallback((row: HTMLElement) => {
    const container = ref.current;
    if (!container || !container.contains(row)) return;
    const containerRect = container.getBoundingClientRect();
    const rowRect = row.getBoundingClientRect();
    const next = { top: rowRect.top - containerRect.top, height: rowRect.height };
    setBox((current) =>
      current && current.top === next.top && current.height === next.height ? current : next,
    );
  }, []);

  const moveTo = useCallback(
    (target: EventTarget | null) => {
      const container = ref.current;
      if (!(target instanceof Element) || !container) return;
      const row = target.closest(rowSelector);
      if (!(row instanceof HTMLElement) || !container.contains(row)) return;
      activeRowRef.current = row;
      measure(row);
      setVisible(true);
    },
    [measure, rowSelector],
  );

  useLayoutEffect(() => {
    const container = ref.current;
    if (!container || typeof ResizeObserver === "undefined") return;
    const update = () => {
      const row = activeRowRef.current;
      if (!row?.isConnected || !container.contains(row)) {
        activeRowRef.current = null;
        setVisible(false);
        return;
      }
      measure(row);
    };
    const observer = new ResizeObserver(update);
    observer.observe(container);
    container.querySelectorAll<HTMLElement>(rowSelector).forEach((row) => observer.observe(row));
    update();
    window.addEventListener("resize", update);
    return () => {
      observer.disconnect();
      window.removeEventListener("resize", update);
    };
  }, [children, measure, rowSelector]);

  const rows = () =>
    Array.from(ref.current?.querySelectorAll<HTMLElement>(rowSelector) ?? []).filter(
      (row) => !row.hasAttribute("disabled") && row.getAttribute("aria-disabled") !== "true",
    );

  const moveFocus = (event: ReactKeyboardEvent<HTMLDivElement>) => {
    if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) return;
    const items = rows();
    if (items.length === 0) return;
    const current =
      event.target instanceof Element
        ? (event.target.closest(rowSelector) as HTMLElement | null)
        : null;
    const currentIndex = current ? items.indexOf(current) : -1;
    const nextIndex =
      event.key === "Home"
        ? 0
        : event.key === "End"
          ? items.length - 1
          : event.key === "ArrowUp"
            ? currentIndex <= 0
              ? items.length - 1
              : currentIndex - 1
            : (currentIndex + 1) % items.length;
    event.preventDefault();
    items[nextIndex]?.focus();
    moveTo(items[nextIndex]);
  };

  const leavePointer = () => {
    const focused = document.activeElement;
    if (focused instanceof Element && ref.current?.contains(focused)) {
      moveTo(focused);
      return;
    }
    activeRowRef.current = null;
    setVisible(false);
  };

  return (
    <div
      ref={ref}
      role={role}
      aria-label={ariaLabel}
      onPointerMove={(event) => moveTo(event.target)}
      onPointerLeave={leavePointer}
      onFocusCapture={(event) => moveTo(event.target)}
      onBlurCapture={(event) => {
        if (!ref.current?.contains(event.relatedTarget as Node | null)) {
          activeRowRef.current = null;
          setVisible(false);
        }
      }}
      onKeyDownCapture={moveFocus}
      className={`group/glide-menu relative ${className}`}
    >
      <span
        aria-hidden
        className={`pointer-events-none absolute ${highlightClassName}`}
        style={{
          top: 0,
          height: box?.height ?? 0,
          opacity: box && visible ? 1 : 0,
          transform: `translate3d(0, ${box?.top ?? 0}px, 0)`,
          willChange: "transform, height, opacity",
          transition: reducedMotion
            ? "none"
            : "transform 240ms cubic-bezier(0.23,1,0.32,1), height 240ms cubic-bezier(0.23,1,0.32,1), opacity 160ms ease",
        }}
      />
      {children}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";

export function useReducedMotion() {
  const [reduced, setReduced] = useState(false);

  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, []);

  return reduced;
}
